{
  "id": "vuln-ckeditor-oembed-plugin-10f6169e",
  "pattern": "'div(embeddedContent,oembed-provider-*) script': { attributes: '*' }",
  "languages": ["javascript"],
  "message": "Potential security vulnerability in CKEditor oEmbed plugin. The pattern allows all attributes on script elements within embedded content, which could enable XSS attacks by permitting malicious script execution. Fix by restricting attribute permissions or sanitizing inputs before embedding.",
  "severity": "ERROR",
  "metadata": {
    "category": "security",
    "cwe": "CWE-79",
    "owasp": "OWASP-A03:2021"
  }
}

